(() => {
  'use strict';
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const view = $('#view');
  const LS = {visitor:'dds_visitor_id',cart:'dds_cart',compare:'dds_compare',recent:'dds_recent',adminTab:'dds_admin_tab',lastOrder:'dds_last_order',lastSeller:'dds_last_seller'};
  const visitorId = localStorage.getItem(LS.visitor) || (() => { const x='visitor_'+crypto.randomUUID(); localStorage.setItem(LS.visitor,x); return x; })();
  let config = {store:{name:'DADDYS STORE',tagline:'THE ULTIMATE BGMI MARKETPLACE',hero_title:'ENTER THE ARMORY',hero_subtitle:'Explore premium inventories, rare collections and authorized UC packages.',hero_image:'/assets/daddys-store-hero.webp'},payments:{upi_enabled:false,whatsapp_enabled:true,telegram_enabled:true,default_method:'whatsapp'}};
  let cachedAccounts = [];
  let adminData = {accounts:[],catalog:[],uc:[],sellers:[],orders:[],settings:null};
  let adminTab = localStorage.getItem(LS.adminTab) || 'overview';
  let accountEditing = null;
  let catalogEditing = null;
  let ucEditing = null;
  let activeDetailTab = 'overview';
  let activeGlacierLevel = 7;

  const esc = (v='') => String(v ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const safeUrl = (v='') => { const s=String(v||'').trim(); if (s.startsWith('/') && !s.startsWith('//')) return s; try { const u=new URL(s, location.origin); return ['http:','https:'].includes(u.protocol) ? u.href : ''; } catch { return ''; } };
  const money = n => '₹'+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:0});
  const lines = s => String(s||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
  const json = (s, fallback={}) => { try { return JSON.parse(s); } catch { return fallback; } };
  const toast = (msg, bad=false) => { const t=$('#toast'); t.textContent=msg; t.style.background=bad?'#ff9ba3':'#e8c17e'; t.classList.add('show'); clearTimeout(toast.t); toast.t=setTimeout(()=>t.classList.remove('show'),2800); };
  const get = (k, fallback) => { try { return JSON.parse(localStorage.getItem(k)) ?? fallback; } catch { return fallback; } };
  const set = (k,v) => localStorage.setItem(k,JSON.stringify(v));
  const cart = () => get(LS.cart,[]);
  const cartCount = () => cart().reduce((n,x)=>n+(x.quantity||1),0);
  const updateCartCount = () => { const el=$('#cart-count'); if(el) el.textContent=cartCount(); };
  const api = async (url, opts={}) => {
    const headers = new Headers(opts.headers||{});
    if (!(opts.body instanceof FormData) && opts.body && !headers.has('Content-Type')) headers.set('Content-Type','application/json');
    if (opts.method && !['GET','HEAD'].includes(opts.method.toUpperCase())) headers.set('X-Requested-With','DADDYS-STORE');
    const res = await fetch(url,{...opts,headers,credentials:'same-origin'});
    const data = await res.json().catch(()=>({detail:'Unexpected server response'}));
    if (!res.ok) throw new Error(data.detail || `Request failed (${res.status})`);
    return data;
  };
  const post = (url,data) => api(url,{method:'POST',body:JSON.stringify(data)});
  const put = (url,data) => api(url,{method:'PUT',body:JSON.stringify(data)});
  const del = url => api(url,{method:'DELETE'});
  const empty = (title,desc,cta='') => `<div class="empty-state"><b>${esc(title)}</b><span>${esc(desc)}</span>${cta?`<div class="spacer"></div>${cta}`:''}</div>`;
  const pageHead = (eyebrow,title,desc='') => `<div class="page-head"><span class="eyebrow">${esc(eyebrow)}</span><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>`;
  const heroImage = () => safeUrl(config.store?.hero_image || '/assets/daddys-store-hero.webp') || '/assets/daddys-store-hero.webp';
  const accountCard = a => {
    const gallery=(a.gallery||[]).map(safeUrl).filter(Boolean); const img=gallery[0]||'';
    const inCompare=get(LS.compare,[]).includes(a.id);
    return `<article class="card">
      <div class="card-media">${img?`<img loading="lazy" src="${esc(img)}" alt="${esc(a.title)}">`:`<div class="card-placeholder">DADDYS</div>`}<span class="tag gold" style="position:absolute;top:12px;left:12px">${a.featured?'FEATURED':'INVENTORY'}</span><span class="tag green" style="position:absolute;top:12px;right:12px">${a.verified?'ADMIN REVIEWED':esc((a.status||'available').toUpperCase())}</span></div>
      <div class="card-body"><h3 class="card-title">${esc(a.title)}</h3><div class="muted" style="font-size:10px">SKU ${esc(a.sku||'—')} · Level ${a.account_level||1}</div>
      <div class="tag-row" style="margin-top:10px"><span class="tag">${a.mythic_count||0} Mythics</span><span class="tag">${a.xsuit_count||0} X-Suits</span><span class="tag">${a.gun_labs||0} Gun Labs</span>${a.glacier_level?`<span class="tag gold">Glacier Lv. ${a.glacier_level}</span>`:''}</div>
      <div class="price-row"><span class="price">${money(a.price)}</span><button class="heart-btn" data-wishlist="${esc(a.id)}" title="Add to wishlist">${'♡'}</button></div>
      <div class="card-actions"><button class="btn btn-small btn-ice" data-account="${esc(a.slug)}">Inspect account</button><button class="btn btn-small btn-ghost" data-compare="${esc(a.id)}">${inCompare?'✓ Compared':'Compare'}</button></div></div>
    </article>`;
  };
  const ucCard = p => `<article class="card"><div class="card-media"><div class="card-placeholder" style="font-size:54px">${Number(p.uc_amount).toLocaleString('en-IN')}<small style="display:block;font:700 13px Manrope;color:var(--ice);text-align:center;letter-spacing:4px">UC</small></div></div><div class="card-body"><h3 class="card-title">${esc(p.name)}</h3><p class="muted">${esc(p.description||'Authorized UC package')}</p><div class="price-row"><span class="price">${money(p.price)}</span><span class="tag">${Number(p.uc_amount).toLocaleString('en-IN')} UC</span></div><button class="btn btn-ice" style="width:100%" data-add-uc="${esc(p.id)}">Add to cart</button></div></article>`;

  async function loadConfig(){ try { config=await api('/api/public/config'); } catch(e){ console.warn(e); } }
  function setNav(){ const hash=location.hash.replace('#','').split('/')[0]||'home'; $$('#main-nav a').forEach(a=>a.classList.toggle('active',a.dataset.link===hash)); }
  function navigate(hash){ location.hash=hash; }

  async function render(){
    setNav(); updateCartCount();
    const raw=location.hash.replace(/^#/,'')||'home'; const [route,...args]=raw.split('/');
    try {
      if(route==='home') return await renderHome();
      if(route==='marketplace') return await renderMarketplace();
      if(route==='account') return await renderAccount(args.join('/'));
      if(route==='armory') return await renderArmory();
      if(route==='uc') return await renderUC();
      if(route==='sell') return await renderSell();
      if(route==='seller-dashboard') return await renderSellerDashboard();
      if(route==='wishlist') return await renderWishlist();
      if(route==='recent') return await renderRecent();
      if(route==='compare') return await renderCompare();
      if(route==='cart') return await renderCart();
      if(route==='customer') return await renderCustomer();
      if(route==='verify-email') return await renderVerifyEmail(args.join('/'));
      if(route==='forgot-password') return await renderForgotPassword();
      if(route==='reset-password') return await renderResetPassword(args.join('/'));
      if(route==='orders') return await renderOrders();
      if(route==='admin') return await renderAdmin();
      if(route==='support') return renderStatic('CUSTOMER SUPPORT','Talk to DADDYS STORE',`<div class="form-card"><p class="muted">For order assistance, contact the store through its configured channels.</p>${contactButtons()}</div>`);
      if(route==='faq') return renderStatic('HELP CENTER','Frequently asked questions',`<div class="form-card"><details open><summary>How do I place an order?</summary><p class="muted">Inspect an available listing, add it to cart and complete checkout using an enabled method.</p></details><details><summary>When is payment confirmed?</summary><p class="muted">UPI references are checked against merchant records. A payment is not marked verified just because a customer returns from a UPI app.</p></details><details><summary>How do I sell an account?</summary><p class="muted">Submit your listing and proof. An admin reviews it before publishing.</p></details></div>`);
      if(route==='terms') return renderStatic('STORE POLICIES','Terms & conditions',`<div class="form-card"><p>Transactions are subject to store policies, applicable law, publisher rules and the seller's documented authority to list and transfer the inventory. Listing status and payment status are separate. A submitted payment reference is not a verified payment.</p></div>`);
      if(route==='privacy') return renderStatic('STORE POLICIES','Privacy policy',`<div class="form-card"><p>Contact, order and seller information is used to process enquiries and transactions. Do not submit passwords, OTPs or recovery credentials. Configure a full privacy notice and data-retention policy before public launch.</p></div>`);
      return renderHome();
    } catch(e){ console.error(e); view.innerHTML=`<div class="section">${empty('Unable to load this page',e.message,'<button class="btn" onclick="location.hash=\'home\'">Back to home</button>')}</div>`; }
  }
  function renderStatic(eyebrow,title,content){ view.innerHTML=pageHead(eyebrow,title)+`<div class="section compact">${content}</div>`; }

  async function renderHome(){
    const [acc,uc]=await Promise.all([api('/api/accounts?sort=newest'),api('/api/uc-packages')]);
    cachedAccounts=acc.items;
    const featured=acc.items.filter(x=>x.featured).slice(0,3); const items=(featured.length?featured:acc.items).slice(0,3);
    view.innerHTML=`<section class="hero"><div class="hero-content"><span class="eyebrow">${esc(config.store?.tagline||'THE ULTIMATE BGMI MARKETPLACE')}</span><h1>${esc(config.store?.hero_title||'ENTER THE')} <span>ARMORY</span></h1><p class="hero-copy">${esc(config.store?.hero_subtitle||'Explore premium inventories, rare collections and authorized UC packages.')}</p><div class="hero-actions"><a class="btn" href="#marketplace">Explore BGMI IDs ↗</a><a class="btn btn-outline" href="#armory">Discover Armory</a><a class="btn btn-ice" href="#sell">Sell your account</a></div><div class="hero-stats"><div class="hero-stat"><b>${acc.count}</b><small>Available listings</small></div><div class="hero-stat"><b>${uc.items.length}</b><small>UC packages</small></div><div class="hero-stat"><b>01–07</b><small>Glacier showcase</small></div></div></div><div class="hero-visual"><img src="${esc(heroImage())}" alt="DADDYS STORE royal warrior" fetchpriority="high"></div></section>
    <div class="feature-strip"><div class="feature-chip"><i>◈</i><div><b>Inventory inspection</b><small>Explore listing details</small></div></div><div class="feature-chip"><i>❄</i><div><b>Glacier showcase</b><small>Seven-level display</small></div></div><div class="feature-chip"><i>✦</i><div><b>DADDYS ARMORY</b><small>Search the collection</small></div></div><div class="feature-chip"><i>↗</i><div><b>Direct support</b><small>WhatsApp & Telegram</small></div></div></div>
    <section class="section"><div class="section-head"><div><span class="eyebrow">CURATED INVENTORY</span><h2>Featured accounts</h2><p>Inspect every available listing before enquiring.</p></div><a href="#marketplace" class="btn btn-outline btn-small">View marketplace ↗</a></div>${items.length?`<div class="grid">${items.map(accountCard).join('')}</div>`:empty('The marketplace is being prepared','No public account listings yet. The admin can publish verified inventory from the dashboard.','<a class="btn btn-outline" href="#sell">Submit your account</a>')}</section>
    <section class="section compact"><div class="section-head"><div><span class="eyebrow">THE SIGNATURE COLLECTION</span><h2>DADDYS ARMORY</h2><p>Browse weapons, suits, vehicles and collectible inventory.</p></div><a href="#armory" class="btn btn-outline btn-small">Explore armory ↗</a></div><div class="grid four"><a class="armory-tile" href="#armory"><div class="armory-icon">❄</div><h3>Glacier Collection</h3><p class="muted">M416 Glacier and other icy weapon skins.</p></a><a class="armory-tile" href="#armory"><div class="armory-icon">♛</div><h3>X-Suit Collection</h3><p class="muted">Inspect X-Suits and star levels.</p></a><a class="armory-tile" href="#armory"><div class="armory-icon">⚔</div><h3>Gun Labs</h3><p class="muted">Weapon skins and upgrade levels.</p></a><a class="armory-tile" href="#armory"><div class="armory-icon">✧</div><h3>Rare Collectibles</h3><p class="muted">Vehicles, emotes and rare items.</p></a></div></section>
    <section class="section"><div class="section-head"><div><span class="eyebrow">AUTHORIZED TOP-UP</span><h2>UC packages</h2><p>Packages and prices are managed by the store admin.</p></div><a href="#uc" class="btn btn-outline btn-small">All packages ↗</a></div>${uc.items.length?`<div class="grid four">${uc.items.slice(0,4).map(ucCard).join('')}</div>`:empty('UC packages are not configured','The admin can publish current authorized packages and prices.')}</section>
    <section class="section compact"><div class="form-card split"><div><span class="eyebrow">HAVE AN INVENTORY TO LIST?</span><h2 class="page-title">Sell with DADDYS STORE</h2><p class="muted">Submit your details and proof. The store team reviews the submission before a listing goes public.</p><a href="#sell" class="btn">Submit a listing ↗</a></div><div class="notice info">Never share passwords, OTPs or recovery credentials. Submit only information and transfers for which you have documented authorization.</div></div></section>`;
  }

  async function renderMarketplace(){
    const q=new URLSearchParams(location.hash.split('?')[1]||'');
    view.innerHTML=pageHead('THE MARKETPLACE','BGMI account inventory','Search and compare listings using price, rarity, Glacier level, X-Suits and collection filters.')+`<section class="section compact"><div class="filters"><div class="field"><label>SEARCH</label><input class="input" id="filter-q" placeholder="Account title, SKU, suit or weapon…" value="${esc(q.get('q')||'')}"></div><div class="field"><label>SORT BY</label><select id="filter-sort"><option value="newest">Newest</option><option value="price_asc">Price: low to high</option><option value="price_desc">Price: high to low</option><option value="mythics">Most mythics</option><option value="views">Most viewed</option></select></div><div class="field"><label>MIN PRICE (₹)</label><input class="input" type="number" min="0" id="filter-min-price" placeholder="No minimum"></div><div class="field"><label>MAX PRICE (₹)</label><input class="input" type="number" min="0" id="filter-max-price" placeholder="No maximum"></div><div class="field"><label>MIN GLACIER LEVEL</label><select id="filter-glacier"><option value="">Any</option>${[1,2,3,4,5,6,7].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>MIN X-SUITS</label><select id="filter-xsuits"><option value="">Any</option>${[1,2,3,4,5,6,7,8,10].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>MIN MYTHICS</label><input class="input" type="number" id="filter-mythics" min="0" placeholder="Any"></div><div class="field"><label>MIN GUN LABS</label><input class="input" type="number" id="filter-gun-labs" min="0" placeholder="Any"></div></div><div class="row" style="justify-content:space-between;margin:10px 0 16px"><span class="muted" id="result-count">Loading listings…</span><button class="btn btn-small btn-ghost" id="clear-filters">Clear filters</button></div><div id="market-results" class="grid"></div></section>`;
    if(q.get('q')) $('#filter-q').value=q.get('q');
    const load=async()=>{const params=new URLSearchParams();const value=id=>$('#'+id)?.value||'';if(value('filter-q'))params.set('q',value('filter-q'));if(value('filter-sort'))params.set('sort',value('filter-sort'));if(value('filter-min-price'))params.set('min_price',value('filter-min-price'));if(value('filter-max-price'))params.set('max_price',value('filter-max-price'));if(value('filter-glacier'))params.set('glacier',value('filter-glacier'));if(value('filter-xsuits'))params.set('xsuits',value('filter-xsuits'));if(value('filter-mythics'))params.set('mythics',value('filter-mythics'));if(value('filter-gun-labs'))params.set('gun_labs',value('filter-gun-labs'));const r=await api('/api/accounts?'+params);cachedAccounts=r.items;$('#result-count').textContent=`${r.count} available listing(s)`;$('#market-results').innerHTML=r.items.length?r.items.map(accountCard).join(''):empty('No matching accounts','Try another search or remove some filters.','<a class="btn btn-outline" href="#sell">Submit an account</a>');};
    ['filter-q','filter-sort','filter-min-price','filter-max-price','filter-glacier','filter-xsuits','filter-mythics','filter-gun-labs'].forEach(id=>$('#'+id).addEventListener(id==='filter-q'?'input':'change',()=>{clearTimeout(load.t);load.t=setTimeout(load,180)}));$('#clear-filters').onclick=()=>{['filter-q','filter-min-price','filter-max-price','filter-glacier','filter-xsuits','filter-mythics','filter-gun-labs'].forEach(id=>$('#'+id).value='');$('#filter-sort').value='newest';load()};await load();
  }

  async function renderAccount(slug){
    if(!slug){navigate('marketplace');return}
    const a=await api('/api/accounts/'+encodeURIComponent(slug));
    const recent=get(LS.recent,[]).filter(x=>x!==a.id);recent.unshift(a.id);set(LS.recent,recent.slice(0,20));
    const gallery=(a.gallery||[]).map(safeUrl).filter(Boolean);let selectedImage=gallery[0]||'';
    const inventory=a.inventory||{};
    const cats=[['overview','Overview'],['suits','Suits & outfits'],['xsuits','X-Suits'],['guns','Gun collection'],['vehicles','Vehicles'],['rare','Rare items'],['glacier','M416 Glacier']];
    const renderItems=key=>{const arr=inventory[key]||[];return arr.length?`<div class="inventory-grid">${arr.map(v=>typeof v==='string'?`<div class="inventory-item"><b>${esc(v)}</b><small>${esc(key)}</small></div>`:`<div class="inventory-item">${v.image?`<img style="width:100%;height:110px;object-fit:cover;border-radius:8px;margin-bottom:8px" src="${esc(safeUrl(v.image))}">`:''}<b>${esc(v.name||'Inventory item')}</b><small>${esc(v.rarity||v.level||'')}</small></div>`).join('')}</div>`:empty('No items added in this category','The seller/admin has not supplied verified entries for this category.')};
    const detailsContent=()=>{if(activeDetailTab==='overview')return `<p class="muted">${esc(a.description||'No additional description supplied.')}</p><div class="stat-grid"><div class="stat-box"><b>${a.mythic_count}</b><small>Mythics</small></div><div class="stat-box"><b>${a.xsuit_count}</b><small>X-Suits</small></div><div class="stat-box"><b>${a.gun_labs}</b><small>Gun labs</small></div><div class="stat-box"><b>${a.account_level}</b><small>Account level</small></div><div class="stat-box"><b>${a.glacier_level||'—'}</b><small>Glacier level</small></div><div class="stat-box"><b>${a.rp_level||'—'}</b><small>RP level</small></div></div><div class="notice info">Counts are seller-submitted and admin-reviewed where explicitly marked. Inspect the gallery and request further proof before proceeding.</div>`;
      if(activeDetailTab==='glacier')return `<div class="glacier-stage"><span class="eyebrow">M416 GLACIER EXPERIENCE</span><h2 class="page-title">LEVEL ${activeGlacierLevel}</h2><div class="level-selector">${[1,2,3,4,5,6,7].map(n=>`<button class="level-btn ${n===activeGlacierLevel?'active':''}" data-glacier-level="${n}">${n}</button>`).join('')}</div>${a.glacier_images?.[activeGlacierLevel]?`<img style="width:100%;max-height:320px;object-fit:contain;border-radius:12px" src="${esc(safeUrl(a.glacier_images[activeGlacierLevel]))}" alt="M416 Glacier level ${activeGlacierLevel}">`:`<div class="empty-state"><b>Level ${activeGlacierLevel} preview not uploaded</b><span>Admin can add the real screenshot for each Glacier level.</span></div>`}<p class="muted">Account's listed Glacier level: ${a.glacier_level||0}. A selected preview level is not proof that the account owns that level.</p></div>`;
      if(activeDetailTab==='xsuits')return renderItems('xsuits');if(activeDetailTab==='suits')return renderItems('suits');if(activeDetailTab==='guns')return renderItems('guns');if(activeDetailTab==='vehicles')return renderItems('vehicles');if(activeDetailTab==='rare')return ['helmets','backpacks','parachutes','emotes','companions','collectibles'].map(k=>`<h3 class="card-title">${esc(k)}</h3>${renderItems(k)}`).join('');return ''};
    view.innerHTML=`${pageHead('ACCOUNT INSPECTION',a.title,`Listing ${a.sku} · Last updated ${new Date(a.updated_at).toLocaleDateString()}${a.verified?' · Admin evidence reviewed':''}`)}<div class="detail-layout"><div><div class="gallery-main">${selectedImage?`<img id="gallery-selected" src="${esc(selectedImage)}" alt="${esc(a.title)}">`:`<div class="card-placeholder">DADDYS STORE</div>`}</div><div class="thumbs">${gallery.map(src=>`<img src="${esc(src)}" data-gallery="${esc(src)}" alt="Account screenshot">`).join('')}</div>${a.video_url?`<div class="notice info"><a href="${esc(safeUrl(a.video_url))}" target="_blank" rel="noopener">▶ Watch inventory proof video ↗</a></div>`:''}<div class="tabs">${cats.map(([k,n])=>`<button class="tab ${k===activeDetailTab?'active':''}" data-detail-tab="${k}">${n}</button>`).join('')}</div><div id="detail-tab-content">${detailsContent()}</div></div><aside class="detail-panel"><span class="eyebrow">${a.featured?'FEATURED INVENTORY':'AVAILABLE LISTING'}</span><h1>${esc(a.title)}</h1><div class="muted">SKU ${esc(a.sku)} · Character level ${a.account_level}</div><div class="price" style="font-size:42px;margin:15px 0">${money(a.price)}</div><div class="tag-row"><span class="tag">${a.mythic_count} Mythics</span><span class="tag">${a.xsuit_count} X-Suits</span><span class="tag">${a.gun_labs} Gun Labs</span>${a.glacier_level?`<span class="tag gold">M416 Glacier Lv.${a.glacier_level}</span>`:''}</div><div class="notice">Ask for a live inventory walkthrough and current ownership proof before payment. Never exchange passwords or OTPs over chat.</div><div class="field"><label>ENQUIRY CHANNEL</label><select id="account-contact">${config.payments?.whatsapp_enabled&&config.store?.whatsapp?'<option value="whatsapp">WhatsApp</option>':''}${config.payments?.telegram_enabled&&config.store?.telegram?'<option value="telegram">Telegram</option>':''}</select></div><button class="btn btn-ice" style="width:100%" id="account-buy">Add to cart & checkout</button><button class="btn" style="width:100%;margin-top:9px" id="account-enquire">Enquire about this account</button><button class="btn btn-outline" style="width:100%;margin-top:9px" id="account-wishlist">♡ Add to wishlist</button><button class="btn btn-ghost" style="width:100%;margin-top:9px" id="account-compare">Compare account</button><div class="admin-form" style="padding:13px;margin-top:17px"><b>Price drop alert</b><div class="field" style="margin-top:9px"><label>EMAIL</label><input class="input" id="price-alert-email" type="email" placeholder="you@example.com"></div><div class="field"><label>NOTIFY ME BELOW (₹)</label><input class="input" id="price-alert-target" type="number" min="1" value="${Math.max(1,Math.floor(a.price*0.9))}"></div><button class="btn btn-small btn-outline" style="width:100%" id="save-price-alert">Create alert</button></div><div class="muted" style="font-size:10px;margin-top:14px">Sale and transfer are subject to applicable rules and seller authorization. Payment is not verified until confirmed by the store.</div></aside></div>`;
    $$('#detail-tab-content [data-glacier-level]').forEach(b=>b.onclick=()=>{activeGlacierLevel=Number(b.dataset.glacierLevel);$('#detail-tab-content').innerHTML=detailsContent()});
    $$('#view [data-detail-tab]').forEach(b=>b.onclick=()=>{activeDetailTab=b.dataset.detailTab;$$('[data-detail-tab]').forEach(x=>x.classList.toggle('active',x===b));$('#detail-tab-content').innerHTML=detailsContent();$$('#detail-tab-content [data-glacier-level]').forEach(x=>x.onclick=()=>{activeGlacierLevel=Number(x.dataset.glacierLevel);$('#detail-tab-content').innerHTML=detailsContent()})});
    $$('#view [data-gallery]').forEach(b=>b.onclick=()=>{$('#gallery-selected').src=b.dataset.gallery});
    $('#account-wishlist').onclick=()=>toggleWishlist(a.id);
    $('#account-compare').onclick=()=>toggleCompare(a.id);
    $('#account-enquire').onclick=()=>contactAccount(a,$('#account-contact').value);
    $('#account-buy').onclick=()=>{const arr=cart();if(!arr.some(x=>x.type==='account'&&x.id===a.id))arr.push({type:'account',id:a.id,quantity:1});set(LS.cart,arr);updateCartCount();navigate('cart')};
    $('#save-price-alert').onclick=async()=>{try{await post('/api/price-alerts',{visitor_id:visitorId,account_id:a.id,email:$('#price-alert-email').value,target_price:+$('#price-alert-target').value});toast('Price alert saved. Email delivery requires store SMTP setup.')}catch(e){toast(e.message,true)}};
  }

  async function renderArmory(){
    view.innerHTML=pageHead('DADDYS ARMORY','Explore the collection','Search catalogued suits, weapons, vehicle skins and collectibles. Item pages show only linked public listings.')+`<section class="section compact"><div class="filters"><div class="field"><label>SEARCH ARMORY</label><input class="input" id="armory-q" placeholder="M416 Glacier, X-Suit, vehicle…"></div><div class="field"><label>CATEGORY</label><select id="armory-cat"><option value="">All categories</option></select></div></div><div id="armory-results" class="grid four"></div></section>`;
    const load=async()=>{const selected=$('#armory-cat').value;const r=await api('/api/armory?category='+encodeURIComponent(selected)+'&q='+encodeURIComponent($('#armory-q').value));$('#armory-cat').innerHTML='<option value="">All categories</option>'+r.categories.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');$('#armory-cat').value=selected;$('#armory-results').innerHTML=r.items.length?r.items.map(i=>`<article class="card"><div class="card-media">${i.image_url?`<img loading="lazy" src="${esc(safeUrl(i.image_url))}" alt="${esc(i.name)}">`:`<div class="card-placeholder">✦</div>`}</div><div class="card-body"><span class="eyebrow">${esc(i.category)}</span><h3 class="card-title">${esc(i.name)}</h3><p class="muted">${esc(i.rarity||i.description||'Catalog item')}</p><div class="tag-row"><span class="tag">${i.accounts.length} linked account(s)</span></div>${i.accounts.length?`<div class="mini-list">${i.accounts.slice(0,4).map(a=>`<a class="tag gold" href="#account/${esc(a.slug)}">${esc(a.title)}</a>`).join('')}</div>`:empty('No available listings','This catalog item is not in a public account right now.')}</div></article>`).join(''):empty('Armory catalog is empty','Admin can add suits, weapon skins, vehicles and rare items from the catalog manager.');};
    $('#armory-q').addEventListener('input',()=>{clearTimeout(load.t);load.t=setTimeout(load,200)});$('#armory-cat').addEventListener('change',load);await load();
  }
  async function renderUC(){const r=await api('/api/uc-packages');view.innerHTML=pageHead('AUTHORIZED TOP-UP','UC Store','Select an available package. Current prices are configured by the store admin.')+`<section class="section compact">${r.items.length?`<div class="grid four">${r.items.map(ucCard).join('')}</div>`:empty('UC packages not available','Please check back later or contact the store.')}</section>`;}

  async function renderSell(){
    view.innerHTML=pageHead('SELL WITH DADDYS STORE','Submit your BGMI account','Share your inventory details and original proof. Admin review is required before a public listing is created.')+`<div class="form-card"><div class="notice info">Submit only inventory and transfers you are authorized to list. Never share passwords, OTPs, recovery codes or login credentials.</div><form id="seller-form"><div class="form-grid"><div class="field"><label>SELLER NAME *</label><input class="input" name="seller_name" required maxlength="100"></div><div class="field"><label>EMAIL *</label><input class="input" type="email" name="email" required></div><div class="field"><label>WHATSAPP NUMBER WITH COUNTRY CODE *</label><input class="input" name="whatsapp" required placeholder="91XXXXXXXXXX"></div><div class="field"><label>EXPECTED PRICE (₹) *</label><input class="input" type="number" min="1" name="expected_price" required></div><div class="field"><label>ACCOUNT TITLE</label><input class="input" name="title" placeholder="e.g. Glacier + X-Suit collection"></div><div class="field"><label>CHARACTER LEVEL</label><input class="input" type="number" min="1" max="100" name="account_level" value="1"></div><div class="field"><label>MYTHIC COUNT</label><input class="input" type="number" min="0" name="mythic_count" value="0"></div><div class="field"><label>LEGENDARY COUNT</label><input class="input" type="number" min="0" name="legendary_count" value="0"></div><div class="field"><label>X-SUIT COUNT</label><input class="input" type="number" min="0" name="xsuit_count" value="0"></div><div class="field"><label>GUN LAB COUNT</label><input class="input" type="number" min="0" name="gun_labs" value="0"></div><div class="field"><label>M416 GLACIER LEVEL (0–7)</label><input class="input" type="number" min="0" max="7" name="glacier_level" value="0"></div><div class="field"><label>RP LEVEL</label><input class="input" type="number" min="0" max="100" name="rp_level" value="0"></div><div class="field"><label>VIDEO PROOF URL (OPTIONAL)</label><input class="input" name="video_url" placeholder="https://…"></div></div><div class="form-grid"><div class="field"><label>SUITS / OUTFITS (ONE PER LINE)</label><textarea name="suits"></textarea></div><div class="field"><label>X-SUITS & STAR LEVELS</label><textarea name="xsuits"></textarea></div><div class="field"><label>GUN SKINS & UPGRADE LEVELS</label><textarea name="guns"></textarea></div><div class="field"><label>VEHICLES</label><textarea name="vehicles"></textarea></div><div class="field"><label>HELMETS / BACKPACKS / PARACHUTES</label><textarea name="helmets"></textarea></div><div class="field"><label>EMOTES / COMPANIONS / RARE ITEMS</label><textarea name="collectibles"></textarea></div></div><div class="field"><label>DESCRIPTION / COLLECTION DETAILS</label><textarea name="description" placeholder="Mention original item details and anything the reviewer should inspect…"></textarea></div><div class="field"><label>UPLOAD ACCOUNT SCREENSHOTS (JPG / PNG / WEBP · MAX 10 MB EACH)</label><input class="input" type="file" name="proof_files" accept="image/jpeg,image/png,image/webp" multiple><small class="muted">Upload up to 10 images. Do not include player passwords, OTPs or recovery information in screenshots.</small></div><div class="field"><label>EXTRA IMAGE URLS (OPTIONAL, ONE PER LINE)</label><textarea name="gallery" placeholder="https://…"></textarea></div><label class="check-option"><input type="checkbox" name="authorization" required> I confirm that I have the required authority to submit this inventory and any proposed transfer.</label><div class="spacer"></div><button class="btn" type="submit">Submit for admin review</button></form><div id="seller-result"></div></div>`;
    $('#seller-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const gallery=lines(f.get('gallery'));const proof=[...f.getAll('proof_files')].filter(x=>x&&x.size);if(proof.length>10){toast('Upload a maximum of 10 proof images',true);return;}for(const file of proof){try{const u=await api('/api/sellers/upload',{method:'POST',body:(()=>{const fd=new FormData();fd.append('file',file);return fd})()});gallery.push(u.url)}catch(err){toast('Proof upload failed: '+err.message,true);return;}}const payload={title:f.get('title')||'BGMI account',account_level:+f.get('account_level'),mythic_count:+f.get('mythic_count'),legendary_count:+f.get('legendary_count'),xsuit_count:+f.get('xsuit_count'),gun_labs:+f.get('gun_labs'),glacier_level:+f.get('glacier_level'),rp_level:+f.get('rp_level'),description:f.get('description'),gallery,video_url:f.get('video_url'),inventory:{suits:lines(f.get('suits')),xsuits:lines(f.get('xsuits')),guns:lines(f.get('guns')),vehicles:lines(f.get('vehicles')),helmets:lines(f.get('helmets')),collectibles:lines(f.get('collectibles'))}};try{const r=await post('/api/sellers',{seller_name:f.get('seller_name'),email:f.get('email'),whatsapp:f.get('whatsapp'),expected_price:+f.get('expected_price'),payload});set(LS.lastSeller,{reference:r.reference,access_token:r.access_token});$('#seller-result').innerHTML=`<div class="notice success"><b>Submission received: ${esc(r.reference)}</b><br>Save this private access token: <code>${esc(r.access_token)}</code><br><a href="#seller-dashboard">Open seller dashboard →</a></div>`;e.currentTarget.reset();}catch(err){toast(err.message,true)}};
  }

  async function renderSellerDashboard(){const saved=get(LS.lastSeller,null);view.innerHTML=pageHead('SELLER PORTAL','Track your submission','Use the private reference and access token you received after submitting your account.')+`<div class="form-card"><form id="seller-lookup"><div class="form-grid"><div class="field"><label>SUBMISSION REFERENCE</label><input class="input" name="reference" value="${esc(saved?.reference||'')}" required></div><div class="field"><label>PRIVATE ACCESS TOKEN</label><input class="input" name="access_token" value="${esc(saved?.access_token||'')}" required></div></div><button class="btn">Check status</button></form><div id="seller-status"></div></div>`;$('#seller-lookup').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await post('/api/sellers/lookup',{reference:f.get('reference'),access_token:f.get('access_token')});$('#seller-status').innerHTML=`<div class="notice success">${esc(r.reference)} · <b>${esc(r.status.toUpperCase())}</b><br>${esc(r.admin_note||'No admin note yet.')}</div>`}catch(err){toast(err.message,true)}}}

  async function renderWishlist(){const r=await api('/api/wishlist?visitor_id='+encodeURIComponent(visitorId));view.innerHTML=pageHead('SAVED INVENTORY','Your wishlist','Saved accounts on this browser.')+`<section class="section compact">${r.items.length?`<div class="grid">${r.items.map(accountCard).join('')}</div>`:empty('Your wishlist is empty','Save accounts to compare and revisit them.')}</section>`;}
  async function toggleWishlist(id){try{const current=await api('/api/wishlist?visitor_id='+encodeURIComponent(visitorId));const exists=current.items.some(x=>x.id===id);if(exists){await api('/api/wishlist?visitor_id='+encodeURIComponent(visitorId)+'&account_id='+encodeURIComponent(id),{method:'DELETE'});toast('Removed from wishlist')}else{await post('/api/wishlist',{visitor_id:visitorId,account_id:id});toast('Added to wishlist')}if(location.hash==='#wishlist')await renderWishlist()}catch(e){toast(e.message,true)}}
  function toggleCompare(id){let arr=get(LS.compare,[]);if(arr.includes(id))arr=arr.filter(x=>x!==id);else if(arr.length>=3){toast('Compare up to 3 accounts',true);return}else arr.push(id);set(LS.compare,arr);toast(arr.includes(id)?'Added to compare':'Removed from compare');if(location.hash==='#compare')renderCompare();}
  async function renderRecent(){const ids=get(LS.recent,[]);const r=await api('/api/accounts');const ordered=ids.map(id=>r.items.find(x=>x.id===id)).filter(Boolean);view.innerHTML=pageHead('YOUR HISTORY','Recently viewed','Accounts you inspected in this browser.')+`<section class="section compact">${ordered.length?`<div class="grid">${ordered.map(accountCard).join('')}</div>`:empty('Nothing viewed yet','Open an account listing and it will appear here.')}</section>`}
  async function renderCompare(){const ids=get(LS.compare,[]);const all=await api('/api/accounts');const xs=all.items.filter(x=>ids.includes(x.id));const fields=[['Price',x=>money(x.price)],['Character level',x=>x.account_level],['Mythics',x=>x.mythic_count],['X-Suits',x=>x.xsuit_count],['Legendary outfits',x=>x.legendary_count],['Gun labs',x=>x.gun_labs],['M416 Glacier',x=>x.glacier_level?`Level ${x.glacier_level}`:'Not listed']];view.innerHTML=pageHead('SIDE BY SIDE','Compare accounts','Compare up to three currently available listings.')+`<section class="section compact">${xs.length?`<div class="table-wrap"><table><thead><tr><th>Specification</th>${xs.map(x=>`<th>${esc(x.title)}</th>`).join('')}</tr></thead><tbody>${fields.map(([n,fn])=>`<tr><td>${n}</td>${xs.map(x=>`<td>${esc(fn(x))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="spacer"></div><button class="btn btn-ghost" id="clear-compare">Clear comparison</button>`:empty('Select accounts to compare','Use the Compare button on account cards.')}</section>`;if($('#clear-compare'))$('#clear-compare').onclick=()=>{set(LS.compare,[]);renderCompare()}}

  async function renderCart(){const items=cart();const [accounts,uc]=await Promise.all([api('/api/accounts'),api('/api/uc-packages')]);const resolved=items.map(i=>{const row=i.type==='account'?accounts.items.find(a=>a.id===i.id):uc.items.find(a=>a.id===i.id);return row?{...i,row}:null}).filter(Boolean);const total=resolved.reduce((n,x)=>n+(x.row.price*(x.type==='uc'?x.quantity:1)),0);const hasMethods=Boolean((config.payments?.upi_enabled&&config.payments?.upi_id)||(config.payments?.whatsapp_enabled&&config.store?.whatsapp)||(config.payments?.telegram_enabled&&config.store?.telegram));view.innerHTML=pageHead('YOUR SELECTION','Shopping cart','Confirm the item details and checkout using an enabled contact/payment method.')+`<section class="section compact"><div class="split"><div class="form-card" style="margin:0"><h2 class="page-title">Your items</h2>${resolved.length?resolved.map((x,i)=>`<div class="cart-line"><div><b>${esc(x.row.title||x.row.name)}</b><div class="muted">${x.type==='uc'?`${x.row.uc_amount} UC · Qty ${x.quantity}`:'Single account listing'}</div><button class="btn btn-small btn-danger" data-remove-cart="${i}">Remove</button></div><b>${money(x.row.price*(x.type==='uc'?x.quantity:1))}</b></div>`).join(''):`<div class="empty-state">Your cart is empty.</div>`}<div class="price-row"><b>Order total</b><span class="price">${money(total)}</span></div></div><div class="form-card" style="margin:0"><h2 class="page-title">Checkout</h2><form id="checkout-form"><div class="field"><label>FULL NAME</label><input class="input" name="customer_name" required></div><div class="field"><label>EMAIL</label><input class="input" type="email" name="email"></div><div class="field"><label>WHATSAPP NUMBER</label><input class="input" name="whatsapp" required></div><div class="field"><label>BGMI PLAYER ID (FOR UC)</label><input class="input" name="player_id" inputmode="numeric" pattern="[0-9]{6,20}" ${resolved.some(x=>x.type==='uc')?'required':''}></div><div class="field"><label>PAYMENT / CONTACT METHOD</label><select name="payment_method">${config.payments?.upi_enabled&&config.payments?.upi_id?`<option value="upi" ${config.payments.default_method==='upi'?'selected':''}>UPI</option>`:''}${config.payments?.whatsapp_enabled&&config.store?.whatsapp?`<option value="whatsapp" ${config.payments.default_method==='whatsapp'?'selected':''}>WhatsApp</option>`:''}${config.payments?.telegram_enabled&&config.store?.telegram?`<option value="telegram" ${config.payments.default_method==='telegram'?'selected':''}>Telegram</option>`:''}</select></div><div class="notice">UPI payment will remain pending until store admin verifies the transaction. WhatsApp/Telegram are enquiry channels, not payment processors.</div>${((config.payments?.upi_enabled&&config.payments?.upi_id)||(config.payments?.whatsapp_enabled&&config.store?.whatsapp)||(config.payments?.telegram_enabled&&config.store?.telegram))?'':'<div class="notice danger">The store has not configured an active checkout method yet.</div>'}<button class="btn" type="submit" ${(!resolved.length||!hasMethods)?'disabled':''}>Create order · ${money(total)}</button></form><div id="checkout-result"></div></div></div></section>`;
    $$('[data-remove-cart]').forEach(b=>b.onclick=()=>{const arr=cart();arr.splice(Number(b.dataset.removeCart),1);set(LS.cart,arr);renderCart();updateCartCount()});
    $('#checkout-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await post('/api/orders',{customer_name:f.get('customer_name'),email:f.get('email'),whatsapp:f.get('whatsapp'),player_id:f.get('player_id'),payment_method:f.get('payment_method'),items:resolved.map(x=>({item_type:x.type,item_id:x.id,quantity:x.type==='uc'?x.quantity:1}))});set(LS.lastOrder,{reference:r.reference,access_token:r.access_token});set(LS.cart,[]);updateCartCount();let redirect='';if(r.payment_method==='upi'&&r.redirect_url)redirect=`${r.dynamic_qr?`<img src="${esc(r.dynamic_qr)}" alt="Exact amount UPI QR" style="max-width:220px;max-height:220px;object-fit:contain;background:#fff;border:1px solid var(--line);border-radius:14px;padding:8px;margin:12px 0">`:r.qr_image?`<img src="${esc(safeUrl(r.qr_image))}" alt="UPI QR" style="max-width:220px;max-height:220px;object-fit:contain;border:1px solid var(--line);border-radius:14px;padding:8px;margin:12px 0">`:''}<a class="btn btn-ice" href="${esc(r.redirect_url)}">Open UPI app chooser ↗</a><div class="muted" style="margin:8px 0">UPI ID: ${esc(r.upi_id||'')}</div><div class="field" style="margin-top:12px"><label>UPI TRANSACTION REFERENCE / UTR</label><input class="input" id="order-utr" placeholder="Enter after payment"></div><button class="btn btn-outline" id="submit-utr">Submit UTR for verification</button>`;else if(r.redirect_url)redirect=`<a class="btn btn-ice" target="_blank" rel="noopener" href="${esc(safeUrl(r.redirect_url))}">Continue to ${esc(r.payment_method)} ↗</a>`;else redirect='<p class="muted">Contact destination is not configured. Please contact store support.</p>';$('#checkout-result').innerHTML=`<div class="notice success"><b>Order created: ${esc(r.reference)}</b><br>Total: ${money(r.total)}<br>Payment status: Pending<br><small>Save this private order access token: ${esc(r.access_token)}</small></div>${redirect}<div class="spacer"></div><a href="#orders" class="btn btn-ghost">Track order</a>`;if($('#submit-utr'))$('#submit-utr').onclick=async()=>{const utr=$('#order-utr').value;try{await post('/api/orders/submit-payment',{reference:r.reference,access_token:r.access_token,utr});toast('UTR submitted. Verification is pending.')}catch(err){toast(err.message,true)}}; }catch(err){toast(err.message,true)}};
  }
  async function renderCustomer(){const me=await api('/api/auth/me');view.innerHTML=pageHead('CUSTOMER ACCOUNT','Sign in or create an account','Email verification is required for customer accounts. Guest order tracking remains available with your private access token.')+`<div class="form-card"><div class="tabs"><button class="tab active" data-auth-tab="login">Sign in</button><button class="tab" data-auth-tab="register">Create account</button></div><div id="auth-area">${me.authenticated?`<div class="notice success">Signed in as ${esc(me.user.name)} (${esc(me.user.email)})</div><button class="btn btn-ice" id="go-orders">View my orders</button> <button class="btn btn-ghost" id="customer-logout">Sign out</button>`:loginForm()}</div></div>`;if(me.authenticated){$('#go-orders').onclick=()=>navigate('orders');$('#customer-logout').onclick=async()=>{await post('/api/auth/logout',{});renderCustomer()}}else bindAuth();}
  function loginForm(){return `<form id="auth-form"><div class="field"><label>EMAIL</label><input class="input" name="username" type="email" required autocomplete="email"></div><div class="field"><label>PASSWORD</label><input class="input" name="password" type="password" minlength="12" required autocomplete="current-password"></div><div class="row" style="justify-content:space-between;margin:10px 0"><a class="text-link" href="#forgot-password">Forgot password?</a><button class="btn btn-ghost btn-small" type="button" id="resend-verification">Resend verification</button></div><button class="btn">Sign in</button></form><div id="auth-feedback"></div>`}
  function registerForm(){return `<form id="auth-form"><div class="field"><label>NAME</label><input class="input" name="name" required maxlength="100" autocomplete="name"></div><div class="field"><label>EMAIL</label><input class="input" name="email" type="email" required autocomplete="email"></div><div class="field"><label>PHONE</label><input class="input" name="phone" autocomplete="tel"></div><div class="field"><label>PASSWORD (12+ CHARACTERS)</label><input class="input" name="password" type="password" minlength="12" required autocomplete="new-password"></div><button class="btn">Create account</button></form><div id="auth-feedback"></div>`}
  function bindAuth(){let mode='login';$$('[data-auth-tab]').forEach(b=>b.onclick=()=>{$$('[data-auth-tab]').forEach(x=>x.classList.toggle('active',x===b));mode=b.dataset.authTab;$('#auth-area').innerHTML=mode==='login'?loginForm():registerForm();bindForm()});bindForm();}
  function bindForm(){const form=$('#auth-form');if(form)form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);const feedback=$('#auth-feedback');try{if(f.has('name')){const r=await post('/api/auth/register',{name:f.get('name'),email:f.get('email'),phone:f.get('phone'),password:f.get('password')});feedback.innerHTML=`<div class="notice info">${esc(r.message||'Check your email for the verification link.')}</div>${r.debug_token?`<div class="notice">Development verification token: <code>${esc(r.debug_token)}</code><br><a href="#verify-email/${encodeURIComponent(r.debug_token)}">Verify test account ↗</a></div>`:''}`;toast('Check your email to verify your account')}else{await post('/api/auth/login',{username:f.get('username'),password:f.get('password')});toast('Welcome to DADDYS STORE');renderCustomer()}}catch(err){feedback.innerHTML=`<div class="notice danger">${esc(err.message)}</div>`;toast(err.message,true)}};
    const resend=$('#resend-verification');if(resend)resend.onclick=async()=>{const email=$('#auth-form [name="username"]')?.value||prompt('Enter the email used for registration:');if(!email)return;try{const r=await post('/api/auth/resend-verification',{email});const fb=$('#auth-feedback');fb.innerHTML=`<div class="notice info">${esc(r.message)}</div>${r.debug_token?`<div class="notice">Development token: <code>${esc(r.debug_token)}</code><br><a href="#verify-email/${encodeURIComponent(r.debug_token)}">Verify test account ↗</a></div>`:''}`;toast('If required, a new verification email was sent')}catch(err){toast(err.message,true)}};
  }
  async function renderVerifyEmail(token){view.innerHTML=pageHead('EMAIL VERIFICATION','Verify your email','This single-use verification link expires after 24 hours.')+`<div class="form-card"><div id="verify-result" class="notice info">Verifying your email…</div></div>`;try{if(!token)throw new Error('Verification token is missing.');const r=await post('/api/auth/verify-email',{token});$('#verify-result').className='notice success';$('#verify-result').textContent=r.message+' You are now signed in.';const b=document.createElement('a');b.className='btn';b.href='#customer';b.textContent='Open your account';$('#verify-result').after(b)}catch(err){$('#verify-result').className='notice danger';$('#verify-result').textContent=err.message+' Return to sign in and request another verification link.'}}
  async function renderForgotPassword(){view.innerHTML=pageHead('ACCOUNT RECOVERY','Forgot password','We will send a one-hour password reset link if a verified account matches the email.')+`<div class="form-card"><form id="forgot-form"><div class="field"><label>ACCOUNT EMAIL</label><input class="input" type="email" name="email" required autocomplete="email"></div><button class="btn">Send reset link</button></form><div id="forgot-result"></div></div>`;$('#forgot-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await post('/api/auth/forgot-password',{email:f.get('email')});$('#forgot-result').innerHTML=`<div class="notice info">${esc(r.message)}</div>${r.debug_token?`<div class="notice">Development reset token: <code>${esc(r.debug_token)}</code><br><a href="#reset-password/${encodeURIComponent(r.debug_token)}">Continue password reset ↗</a></div>`:''}`}catch(err){toast(err.message,true)}}}
  async function renderResetPassword(token){view.innerHTML=pageHead('ACCOUNT RECOVERY','Create a new password','Use a strong password of at least 12 characters. Reset links can only be used once.')+`<div class="form-card"><form id="reset-form"><div class="field"><label>NEW PASSWORD</label><input class="input" name="password" type="password" minlength="12" required autocomplete="new-password"></div><div class="field"><label>CONFIRM PASSWORD</label><input class="input" name="confirm" type="password" minlength="12" required autocomplete="new-password"></div><button class="btn">Update password</button></form><div id="reset-result"></div></div>`;$('#reset-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(f.get('password')!==f.get('confirm')){toast('Passwords do not match',true);return}try{const r=await post('/api/auth/reset-password',{token,new_password:f.get('password')});$('#reset-result').innerHTML=`<div class="notice success">${esc(r.message)}</div><a class="btn" href="#customer">Sign in</a>`}catch(err){toast(err.message,true)}}}
  async function renderOrders(){const saved=get(LS.lastOrder,null);view.innerHTML=pageHead('ORDER TRACKING','My orders','Sign in to see your central order history, or use the private reference and access token from guest checkout.')+`<div class="form-card"><div id="customer-orders"></div><h3 class="card-title">Track a guest order</h3><form id="order-lookup"><div class="form-grid"><div class="field"><label>ORDER REFERENCE</label><input class="input" name="reference" value="${esc(saved?.reference||'')}" required></div><div class="field"><label>PRIVATE ACCESS TOKEN</label><input class="input" name="access_token" required></div></div><button class="btn">Find order</button></form><div id="order-status"></div></div>`;try{const r=await api('/api/customer/orders');$('#customer-orders').innerHTML=`<h2 class="page-title">Signed-in order history</h2>${r.items.length?r.items.map(x=>`<div class="cart-line"><div><b>${esc(x.reference)}</b><div class="muted">${esc(x.status)} · Payment: ${esc(x.payment_status)}</div></div><b>${money(x.total)}</b></div>`).join(''):'<p class="muted">No account orders found.</p>'}`}catch{}$('#order-lookup').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const r=await post('/api/orders/lookup',{reference:f.get('reference'),access_token:f.get('access_token')});$('#order-status').innerHTML=`<div class="notice success">${esc(r.reference)}<br>Order: ${esc(r.status)} · Payment: ${esc(r.payment_status)}<br>Total: ${money(r.total)}<br>${esc(r.admin_note||'')}</div>`}catch(err){toast(err.message,true)}}}
  function contactAccount(a,method){const msg=`DADDYS STORE enquiry for ${a.title} (${a.sku}) · Price ${money(a.price)} · Listing ${a.slug}`;if(method==='whatsapp'){const phone=String(config.store?.whatsapp||'').replace(/\D/g,'');if(!phone){toast('WhatsApp number not configured',true);return}window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank','noopener')}else{let tg=config.store?.telegram||'';if(!tg){toast('Telegram link not configured',true);return}if(tg.startsWith('@'))tg='https://t.me/'+tg.slice(1);else if(!/^https?:\/\//i.test(tg))tg='https://t.me/'+tg.replace(/^\//,'');window.open(tg,'_blank','noopener')}}

  // ---------------- ADMIN UI ----------------
  async function renderAdmin(){
    try{await api('/api/admin/me')}catch{view.innerHTML=pageHead('PRIVATE ADMIN','Admin sign in','This route is not linked in the public navigation. Access is protected by server-side authentication.')+`<div class="form-card" style="max-width:480px"><form id="admin-login"><div class="field"><label>ADMIN USERNAME</label><input class="input" name="username" required autocomplete="username"></div><div class="field"><label>PASSWORD</label><input class="input" type="password" name="password" required autocomplete="current-password"></div><button class="btn" style="width:100%">Secure sign in</button></form></div>`;$('#admin-login').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await post('/api/admin/login',{username:f.get('username'),password:f.get('password')});renderAdmin()}catch(err){toast(err.message,true)}};return}
    await loadAdminData();
    const tabs=[['overview','Overview'],['accounts','Account inventory'],['catalog','Armory catalog'],['uc','UC packages'],['sellers','Seller submissions'],['orders','Orders & payments'],['settings','Store settings'],['audit','Audit log']];
    view.innerHTML=`<div class="admin-shell"><aside class="admin-sidebar"><span class="eyebrow" style="padding:8px 12px;display:block">DADDYS CONTROL</span>${tabs.map(([k,n])=>`<button class="${adminTab===k?'active':''}" data-admin-tab="${k}">${n}</button>`).join('')}<div class="spacer"></div><button id="admin-logout">↗ Sign out</button></aside><section class="admin-content" id="admin-content">${adminTab==='overview'?adminOverview():adminTab==='accounts'?adminAccounts():adminTab==='catalog'?adminCatalog():adminTab==='uc'?adminUC():adminTab==='sellers'?adminSellers():adminTab==='orders'?adminOrders():adminTab==='settings'?adminSettings():adminAudit()}</section></div>`;
    $$('[data-admin-tab]').forEach(b=>b.onclick=()=>{adminTab=b.dataset.adminTab;localStorage.setItem(LS.adminTab,adminTab);renderAdmin()});$('#admin-logout').onclick=async()=>{await post('/api/admin/logout',{});navigate('admin')};bindAdminTab();
  }
  async function loadAdminData(){const [dash,accounts,catalog,uc,sellers,orders,settings]=await Promise.all([api('/api/admin/dashboard'),api('/api/admin/accounts'),api('/api/admin/catalog'),api('/api/admin/uc'),api('/api/admin/sellers'),api('/api/admin/orders'),api('/api/admin/settings')]);adminData={dash,accounts:accounts.items,catalog:catalog.items,uc:uc.items,sellers:sellers.items,orders:orders.items,settings}}
  function adminOverview(){const d=adminData.dash;return `<div class="admin-title"><div><span class="eyebrow">STORE OPERATIONS</span><h1>Dashboard</h1></div><span class="tag green">Connected to database</span></div><div class="metric-grid">${[['Available accounts',d.available_accounts],['UC packages',d.uc_packages],['Orders',d.orders],['Pending sellers',d.seller_submissions],['Pending orders',d.pending_orders],['Catalog items',d.catalog_items],['Total listings',d.accounts],['Account views',d.account_views],['Verified revenue',money(d.verified_revenue)]].map(([n,v])=>`<div class="metric"><b>${esc(v)}</b><small>${esc(n)}</small></div>`).join('')}</div><div class="section-head"><h2>Recent orders</h2></div>${d.recent_orders.length?`<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Total</th><th>Order status</th><th>Payment</th></tr></thead><tbody>${d.recent_orders.map(o=>`<tr><td>${esc(o.reference)}</td><td>${esc(o.customer_name)}</td><td>${money(o.total)}</td><td>${esc(o.status)}</td><td>${esc(o.payment_status)}</td></tr>`).join('')}</tbody></table></div>`:empty('No orders yet','New customer orders will appear here.')}<div class="spacer"></div><h2 class="page-title">Most viewed listings</h2>${d.popular_accounts?.length?`<div class="table-wrap"><table><thead><tr><th>Listing</th><th>SKU</th><th>Views</th><th>Price</th><th>Status</th></tr></thead><tbody>${d.popular_accounts.map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.sku)}</td><td>${x.views}</td><td>${money(x.price)}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('No listing views yet','Views are counted when public detail pages are opened.')}`}
  function adminAccounts(){return `<div class="admin-title"><div><span class="eyebrow">NO-CODE INVENTORY BUILDER</span><h1>Account inventory</h1></div><button class="btn btn-small" id="new-account">+ Add account</button></div><p class="muted">Create and manage account listings, attach catalog items, upload proof and choose the public status.</p><div id="account-editor"></div><div class="table-wrap"><table><thead><tr><th>Listing</th><th>SKU</th><th>Price</th><th>Status</th><th>Evidence</th><th>Glacier</th><th>Views</th><th>Actions</th></tr></thead><tbody>${adminData.accounts.map(a=>`<tr><td>${esc(a.title)}</td><td>${esc(a.sku)}</td><td>${money(a.price)}</td><td>${esc(a.status)}</td><td>${a.verified?'Reviewed':'Pending review'}</td><td>${a.glacier_level||'—'}</td><td>${a.views||0}</td><td><button class="btn btn-small btn-ghost" data-edit-account="${a.id}">Edit</button><button class="btn btn-small btn-ghost" data-dup-account="${a.id}">Duplicate</button><button class="btn btn-small btn-danger" data-delete-account="${a.id}">Delete</button></td></tr>`).join('')}</tbody></table></div>`}
  function accountEditor(a={}){accountEditing=a.id||null;const inv=a.inventory||{};const text=k=>(inv[k]||[]).map(x=>typeof x==='string'?x:x.name||'').join('\n');return `<div class="admin-form"><div class="admin-title"><h2>${a.id?'Edit listing':'Create listing'}</h2><button class="btn btn-small btn-ghost" id="close-account-editor">Close</button></div><form id="account-form"><div class="form-grid"><div class="field"><label>LISTING TITLE *</label><input class="input" name="title" required value="${esc(a.title||'')}"></div><div class="field"><label>SKU *</label><input class="input" name="sku" required value="${esc(a.sku||'')}"></div><div class="field"><label>PRICE (₹) *</label><input class="input" name="price" type="number" min="0" required value="${esc(a.price??'')}"></div><div class="field"><label>PUBLIC STATUS</label><select name="status">${['draft','available','reserved','sold'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>ACCOUNT LEVEL</label><input class="input" name="account_level" type="number" min="1" max="100" value="${a.account_level||1}"></div><div class="field"><label>MYTHIC COUNT</label><input class="input" name="mythic_count" type="number" min="0" value="${a.mythic_count||0}"></div><div class="field"><label>LEGENDARY COUNT</label><input class="input" name="legendary_count" type="number" min="0" value="${a.legendary_count||0}"></div><div class="field"><label>X-SUIT COUNT</label><input class="input" name="xsuit_count" type="number" min="0" value="${a.xsuit_count||0}"></div><div class="field"><label>GUN LAB COUNT</label><input class="input" name="gun_labs" type="number" min="0" value="${a.gun_labs||0}"></div><div class="field"><label>M416 GLACIER LEVEL (0–7)</label><input class="input" name="glacier_level" type="number" min="0" max="7" value="${a.glacier_level||0}"></div><div class="field"><label>RP LEVEL</label><input class="input" name="rp_level" type="number" min="0" max="100" value="${a.rp_level||0}"></div><div class="field"><label>VIDEO PROOF URL</label><input class="input" name="video_url" value="${esc(a.video_url||'')}"></div></div><div class="field"><label>DESCRIPTION</label><textarea name="description">${esc(a.description||'')}</textarea></div><div class="form-grid"><div class="field"><label>SUITS (ONE PER LINE)</label><textarea name="suits">${esc(text('suits'))}</textarea></div><div class="field"><label>X-SUITS (ONE PER LINE; INCLUDE STAR LEVEL)</label><textarea name="xsuits">${esc(text('xsuits'))}</textarea></div><div class="field"><label>GUNS / GUN LABS (ONE PER LINE)</label><textarea name="guns">${esc(text('guns'))}</textarea></div><div class="field"><label>VEHICLES (ONE PER LINE)</label><textarea name="vehicles">${esc(text('vehicles'))}</textarea></div><div class="field"><label>HELMETS</label><textarea name="helmets">${esc(text('helmets'))}</textarea></div><div class="field"><label>BACKPACKS</label><textarea name="backpacks">${esc(text('backpacks'))}</textarea></div><div class="field"><label>PARACHUTES</label><textarea name="parachutes">${esc(text('parachutes'))}</textarea></div><div class="field"><label>EMOTES</label><textarea name="emotes">${esc(text('emotes'))}</textarea></div><div class="field"><label>COMPANIONS</label><textarea name="companions">${esc(text('companions'))}</textarea></div><div class="field"><label>RARE COLLECTIBLES</label><textarea name="collectibles">${esc(text('collectibles'))}</textarea></div></div><div class="field"><label>GALLERY IMAGE URLS (ONE PER LINE)</label><textarea name="gallery">${esc((a.gallery||[]).join('\n'))}</textarea></div><div class="field"><label>UPLOAD GALLERY IMAGES (MAX 25 MB EACH)</label><input class="input" type="file" name="gallery_files" accept="image/png,image/jpeg,image/webp,image/gif" multiple></div><div class="field"><label>UPLOAD VIDEO PROOF (OPTIONAL)</label><input class="input" type="file" name="video_file" accept="video/mp4,video/webm"></div><div class="field"><label>GLACIER SCREENSHOTS — JSON LEVEL:URL (OPTIONAL)</label><textarea name="glacier_images" placeholder='{"1":"https://…","7":"https://…"}'>${esc(JSON.stringify(a.glacier_images||{},null,2))}</textarea></div><div class="form-grid">${[1,2,3,4,5,6,7].map(n=>`<div class="field"><label>UPLOAD GLACIER LEVEL ${n} SCREENSHOT</label><input class="input" type="file" name="glacier_file_${n}" accept="image/png,image/jpeg,image/webp"></div>`).join('')}</div><div class="field"><label>LINK CATALOG ITEMS</label><div class="check-grid">${adminData.catalog.map(c=>`<label class="check-option"><input type="checkbox" name="catalog_item_ids" value="${c.id}" ${(a.catalog_items||[]).some(x=>x.id===c.id)?'checked':''}> ${esc(c.name)} <small>· ${esc(c.category)}</small></label>`).join('')||'<span class="muted">Add catalog items first.</span>'}</div></div><label class="check-option"><input type="checkbox" name="featured" ${a.featured?'checked':''}> Feature this listing on the homepage</label><label class="check-option"><input type="checkbox" name="verified" ${a.verified?'checked':''}> Admin evidence reviewed (only check after inspecting seller proof)</label><div class="spacer"></div><button class="btn" type="submit">Save account listing</button></form></div>`}
  function adminCatalog(){return `<div class="admin-title"><div><span class="eyebrow">ARMORY ITEM DATABASE</span><h1>Catalog manager</h1></div><button class="btn btn-small" id="new-catalog">+ Add catalog item</button></div><div id="catalog-editor"></div><div class="grid four">${adminData.catalog.map(c=>`<article class="card"><div class="card-media">${c.image_url?`<img src="${esc(safeUrl(c.image_url))}" alt="">`:`<div class="card-placeholder">✦</div>`}</div><div class="card-body"><span class="eyebrow">${esc(c.category)}</span><h3 class="card-title">${esc(c.name)}</h3><p class="muted">${esc(c.rarity||'')}</p><button class="btn btn-small btn-ghost" data-edit-catalog="${c.id}">Edit</button><button class="btn btn-small btn-danger" data-delete-catalog="${c.id}">Delete</button></div></article>`).join('')}</div>${!adminData.catalog.length?empty('No catalog items yet','Add verified suits, weapons, vehicles and collectibles.'):''}`}
  function catalogEditor(c={}){catalogEditing=c.id||null;return `<div class="admin-form"><div class="admin-title"><h2>${c.id?'Edit catalog item':'Add catalog item'}</h2><button class="btn btn-small btn-ghost" id="close-catalog-editor">Close</button></div><form id="catalog-form"><div class="form-grid"><div class="field"><label>ITEM NAME</label><input class="input" name="name" required value="${esc(c.name||'')}"></div><div class="field"><label>CATEGORY</label><select name="category">${['Glacier Collection','Weapon Skin','X-Suit','Suit / Outfit','Vehicle','Helmet','Backpack','Parachute','Emote','Companion','Rare Collectible','Royal Pass'].map(x=>`<option ${c.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>RARITY / STAR LEVEL</label><input class="input" name="rarity" value="${esc(c.rarity||'')}"></div><div class="field"><label>IMAGE URL</label><input class="input" name="image_url" value="${esc(c.image_url||'')}"></div><div class="field"><label>UPLOAD ITEM IMAGE</label><input class="input" type="file" name="item_image" accept="image/png,image/jpeg,image/webp,image/gif"></div></div><div class="field"><label>DESCRIPTION</label><textarea name="description">${esc(c.description||'')}</textarea></div><label class="check-option"><input type="checkbox" name="active" ${c.active!==false?'checked':''}> Active in public Armory</label><div class="spacer"></div><button class="btn">Save catalog item</button></form></div>`}
  function adminUC(){return `<div class="admin-title"><div><span class="eyebrow">AUTHORIZED TOP-UP</span><h1>UC packages</h1></div><button class="btn btn-small" id="new-uc">+ Add package</button></div><div id="uc-editor"></div><div class="table-wrap"><table><thead><tr><th>Package</th><th>SKU</th><th>UC</th><th>Price</th><th>Active</th><th>Actions</th></tr></thead><tbody>${adminData.uc.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.sku)}</td><td>${p.uc_amount}</td><td>${money(p.price)}</td><td>${p.active?'Yes':'No'}</td><td><button class="btn btn-small btn-ghost" data-edit-uc="${p.id}">Edit</button><button class="btn btn-small btn-danger" data-delete-uc="${p.id}">Disable</button></td></tr>`).join('')}</tbody></table></div>`}
  function ucEditor(p={}){ucEditing=p.id||null;return `<div class="admin-form"><div class="admin-title"><h2>${p.id?'Edit UC package':'Add UC package'}</h2><button class="btn btn-small btn-ghost" id="close-uc-editor">Close</button></div><form id="uc-form"><div class="form-grid"><div class="field"><label>PACKAGE NAME</label><input class="input" name="name" required value="${esc(p.name||'')}"></div><div class="field"><label>SKU</label><input class="input" name="sku" required value="${esc(p.sku||'')}"></div><div class="field"><label>UC AMOUNT</label><input class="input" name="uc_amount" type="number" min="1" required value="${p.uc_amount||''}"></div><div class="field"><label>PRICE (₹)</label><input class="input" name="price" type="number" min="0" required value="${p.price??''}"></div><div class="field"><label>SORT ORDER</label><input class="input" name="sort_order" type="number" min="0" value="${p.sort_order||0}"></div></div><div class="field"><label>DESCRIPTION</label><textarea name="description">${esc(p.description||'')}</textarea></div><label class="check-option"><input type="checkbox" name="active" ${p.active!==false?'checked':''}> Active</label><div class="spacer"></div><button class="btn">Save package</button></form></div>`}
  function adminSellers(){return `<div class="admin-title"><div><span class="eyebrow">SELLER REVIEW QUEUE</span><h1>Seller submissions</h1></div></div>${adminData.sellers.length?`<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Seller</th><th>Expected</th><th>Status</th><th>Submitted</th><th>Review</th></tr></thead><tbody>${adminData.sellers.map(s=>`<tr><td>${esc(s.reference)}</td><td>${esc(s.seller_name)}<br><small>${esc(s.whatsapp)}</small></td><td>${money(s.expected_price)}</td><td>${esc(s.status)}</td><td>${new Date(s.created_at).toLocaleDateString()}</td><td><button class="btn btn-small btn-ghost" data-review-seller="${s.id}">Review</button></td></tr>`).join('')}</tbody></table></div><div id="seller-review"></div>`:empty('No seller submissions','New submissions will appear here after sellers submit the form.')}`}
  function adminOrders(){return `<div class="admin-title"><div><span class="eyebrow">CHECKOUT OPERATIONS</span><h1>Orders & payments</h1></div></div>${adminData.orders.length?`<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Method</th><th>Total</th><th>Status</th><th>Payment</th><th>Review</th></tr></thead><tbody>${adminData.orders.map(o=>`<tr><td>${esc(o.reference)}</td><td>${esc(o.customer_name)}<br><small>${esc(o.whatsapp)}</small></td><td>${esc(o.payment_method)}</td><td>${money(o.total)}</td><td>${esc(o.status)}</td><td>${esc(o.payment_status)}${o.payment_ref?`<br>UTR: ${esc(o.payment_ref)}`:''}</td><td><button class="btn btn-small btn-ghost" data-review-order="${o.id}">Update</button></td></tr>`).join('')}</tbody></table></div><div id="order-review"></div>`:empty('No orders yet','Orders created from the public checkout will appear here.')}`}
  function adminSettings(){const s=adminData.settings;return `<div class="admin-title"><div><span class="eyebrow">STORE CONFIGURATION</span><h1>Settings</h1></div></div><div class="admin-form"><form id="settings-form"><h2 class="card-title">Brand and contacts</h2><div class="form-grid"><div class="field"><label>STORE NAME</label><input class="input" name="store.name" value="${esc(s.store.name||'DADDYS STORE')}"></div><div class="field"><label>TAGLINE</label><input class="input" name="store.tagline" value="${esc(s.store.tagline||'')}"></div><div class="field"><label>WHATSAPP NUMBER WITH COUNTRY CODE</label><input class="input" name="store.whatsapp" value="${esc(s.store.whatsapp||'')}"></div><div class="field"><label>TELEGRAM URL / USERNAME</label><input class="input" name="store.telegram" value="${esc(s.store.telegram||'')}"></div><div class="field"><label>SUPPORT EMAIL</label><input class="input" name="store.support_email" value="${esc(s.store.support_email||'')}"></div><div class="field"><label>HERO IMAGE URL</label><input class="input" name="store.hero_image" value="${esc(s.store.hero_image||'')}"></div><div class="field"><label>UPLOAD HERO IMAGE</label><input class="input" type="file" name="store.hero_upload" accept="image/png,image/jpeg,image/webp"></div></div><div class="field"><label>HERO HEADLINE</label><input class="input" name="store.hero_title" value="${esc(s.store.hero_title||'')}"></div><div class="field"><label>HERO SUBTITLE</label><textarea name="store.hero_subtitle">${esc(s.store.hero_subtitle||'')}</textarea></div><h2 class="card-title">Payment channels</h2><div class="form-grid"><div class="field"><label>MERCHANT UPI ID</label><input class="input" name="payments.upi_id" value="${esc(s.payments.upi_id||'')}"></div><div class="field"><label>PAYEE NAME</label><input class="input" name="payments.payee_name" value="${esc(s.payments.payee_name||'DADDYS STORE')}"></div><div class="field"><label>QR IMAGE URL</label><input class="input" name="payments.qr_image" value="${esc(s.payments.qr_image||'')}"></div><div class="field"><label>UPLOAD UPI QR IMAGE</label><input class="input" type="file" name="payments.qr_upload" accept="image/png,image/jpeg,image/webp"></div><div class="field"><label>DEFAULT CHECKOUT METHOD</label><select name="payments.default_method">${['upi','whatsapp','telegram'].map(x=>`<option ${s.payments.default_method===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label>PAYMENT INSTRUCTIONS</label><textarea name="payments.instructions">${esc(s.payments.instructions||'')}</textarea></div><div class="check-grid"><label class="check-option"><input type="checkbox" name="payments.upi_enabled" ${s.payments.upi_enabled?'checked':''}> Enable UPI</label><label class="check-option"><input type="checkbox" name="payments.whatsapp_enabled" ${s.payments.whatsapp_enabled?'checked':''}> Enable WhatsApp</label><label class="check-option"><input type="checkbox" name="payments.telegram_enabled" ${s.payments.telegram_enabled?'checked':''}> Enable Telegram</label><label class="check-option"><input type="checkbox" name="policies.account_sales_enabled" ${s.policies.account_sales_enabled?'checked':''}> Accept seller submissions</label></div><div class="spacer"></div><button class="btn">Save settings</button></form></div><div class="admin-form"><h2 class="card-title">Change admin password</h2><form id="admin-password-form"><div class="form-grid"><div class="field"><label>CURRENT PASSWORD</label><input class="input" type="password" name="current_password" required></div><div class="field"><label>NEW PASSWORD (14+ CHARACTERS)</label><input class="input" type="password" name="new_password" minlength="14" required></div></div><button class="btn btn-outline">Update password</button></form></div><div class="admin-form"><h2 class="card-title">Inventory backup & restore</h2><p class="muted">Export catalog items, UC packages and account inventory as JSON. Import performs a merge by SKU and catalog name/category; it does not delete unlisted records.</p><div class="row"><button class="btn btn-outline" id="inventory-export">Export JSON backup</button><label class="btn btn-ghost" for="inventory-import-file">Choose backup file</label><input class="hide" id="inventory-import-file" type="file" accept="application/json,.json"><button class="btn btn-ice" id="inventory-import">Import selected JSON</button></div><div id="inventory-backup-status" class="muted" style="margin-top:10px"></div></div><div class="notice info">For price-drop emails, configure SMTP_HOST, SMTP_PORT, SMTP_USER, SMTP_PASSWORD and SMTP_FROM in the server environment. Never place email credentials here.</div>`}
  function adminAudit(){return `<div class="admin-title"><div><span class="eyebrow">SECURITY</span><h1>Audit log</h1></div></div><div id="audit-list">Loading audit history…</div>`}
  async function bindAdminTab(){
    const viewAdmin=$('#admin-content');if(!viewAdmin)return;
    if(adminTab==='accounts'){
      $('#new-account').onclick=()=>{$('#account-editor').innerHTML=accountEditor();bindAccountForm()};
      $$('[data-edit-account]').forEach(b=>b.onclick=()=>{const a=adminData.accounts.find(x=>x.id===b.dataset.editAccount);$('#account-editor').innerHTML=accountEditor(a);bindAccountForm()});
      $$('[data-dup-account]').forEach(b=>b.onclick=async()=>{try{await post(`/api/admin/accounts/${b.dataset.dupAccount}/duplicate`,{});toast('Draft copy created');renderAdmin()}catch(e){toast(e.message,true)}});
      $$('[data-delete-account]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this account listing?'))return;try{await del(`/api/admin/accounts/${b.dataset.deleteAccount}`);toast('Listing deleted');renderAdmin()}catch(e){toast(e.message,true)}});
    }
    if(adminTab==='catalog'){
      $('#new-catalog').onclick=()=>{$('#catalog-editor').innerHTML=catalogEditor();bindCatalogForm()};
      $$('[data-edit-catalog]').forEach(b=>b.onclick=()=>{const c=adminData.catalog.find(x=>x.id===b.dataset.editCatalog);$('#catalog-editor').innerHTML=catalogEditor(c);bindCatalogForm()});
      $$('[data-delete-catalog]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete catalog item?'))return;try{await del(`/api/admin/catalog/${b.dataset.deleteCatalog}`);renderAdmin()}catch(e){toast(e.message,true)}});
    }
    if(adminTab==='uc'){
      $('#new-uc').onclick=()=>{$('#uc-editor').innerHTML=ucEditor();bindUCForm()};
      $$('[data-edit-uc]').forEach(b=>b.onclick=()=>{const p=adminData.uc.find(x=>x.id===b.dataset.editUc);$('#uc-editor').innerHTML=ucEditor(p);bindUCForm()});
      $$('[data-delete-uc]').forEach(b=>b.onclick=async()=>{if(!confirm('Disable this UC package?'))return;try{await del(`/api/admin/uc/${b.dataset.deleteUc}`);renderAdmin()}catch(e){toast(e.message,true)}});
    }
    if(adminTab==='sellers'){
      $$('[data-review-seller]').forEach(b=>b.onclick=()=>{const s=adminData.sellers.find(x=>x.id===b.dataset.reviewSeller);const proof=(s.payload?.gallery||[]).map(safeUrl).filter(Boolean);$('#seller-review').innerHTML=`<div class="admin-form"><h2>${esc(s.reference)} · ${esc(s.seller_name)}</h2><p class="muted">${esc(s.email)} · ${esc(s.whatsapp)} · Expected ${money(s.expected_price)}</p>${proof.length?`<div class="thumbs">${proof.map(src=>`<a href="${esc(src)}" target="_blank" rel="noopener"><img src="${esc(src)}" alt="Seller proof screenshot"></a>`).join('')}</div>`:''}<pre style="white-space:pre-wrap;color:#b7c8d9">${esc(JSON.stringify(s.payload,null,2))}</pre><div class="form-grid"><div class="field"><label>STATUS</label><select id="seller-status">${['pending','reviewing','approved','rejected','published','withdrawn'].map(x=>`<option ${s.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>ADMIN NOTE</label><input class="input" id="seller-note" value="${esc(s.admin_note||'')}"></div></div><button class="btn" id="save-seller">Save review</button></div>`;$('#save-seller').onclick=async()=>{try{const status=$('#seller-status').value;const r=await put(`/api/admin/sellers/${s.id}`,{status,admin_note:$('#seller-note').value});toast(r.created_draft_account_id?'Approved; draft listing created. Publish it from Account inventory.':'Seller status updated');renderAdmin()}catch(e){toast(e.message,true)}}});
    }
    if(adminTab==='orders'){
      $$('[data-review-order]').forEach(b=>b.onclick=()=>{const o=adminData.orders.find(x=>x.id===b.dataset.reviewOrder);$('#order-review').innerHTML=`<div class="admin-form"><h2>${esc(o.reference)}</h2><p class="muted">${esc(o.customer_name)} · ${esc(o.whatsapp)} · ${money(o.total)}</p><pre style="white-space:pre-wrap;color:#b7c8d9">${esc(JSON.stringify(o.items,null,2))}</pre><p>Submitted payment reference: <b>${esc(o.payment_ref||'Not submitted')}</b></p><div class="form-grid"><div class="field"><label>ORDER STATUS</label><select id="order-status">${['pending','processing','completed','cancelled','refunded'].map(x=>`<option ${o.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>PAYMENT STATUS</label><select id="payment-status">${['pending','submitted','verified','failed','refunded'].map(x=>`<option ${o.payment_status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>PAYMENT REFERENCE / UTR</label><input class="input" id="payment-ref" value="${esc(o.payment_ref||'')}"></div><div class="field"><label>ADMIN NOTE</label><input class="input" id="order-note" value="${esc(o.admin_note||'')}"></div></div><div class="notice">Only select “verified” after checking the transaction in the merchant account or payment gateway dashboard.</div><button class="btn" id="save-order">Save order</button></div>`;$('#save-order').onclick=async()=>{try{await put(`/api/admin/orders/${o.id}`,{status:$('#order-status').value,payment_status:$('#payment-status').value,payment_ref:$('#payment-ref').value,admin_note:$('#order-note').value});toast('Order updated');renderAdmin()}catch(e){toast(e.message,true)}}});
    }
    if(adminTab==='settings'){
      $('#settings-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const s=adminData.settings;const store={...s.store};const payments={...s.payments};const policies={...s.policies};const heroFile=f.get('store.hero_upload');const qrFile=f.get('payments.qr_upload');if(heroFile&&heroFile.size){try{store.hero_image=(await uploadFile(heroFile)).url}catch(err){toast('Hero image upload failed: '+err.message,true);return}}if(qrFile&&qrFile.size){try{payments.qr_image=(await uploadFile(qrFile)).url}catch(err){toast('QR image upload failed: '+err.message,true);return}}for(const [k,v] of f.entries()){if(v instanceof File)continue;if(k==='store.hero_upload'||k==='payments.qr_upload')continue;if(k==='store.hero_image'&&heroFile&&heroFile.size)continue;if(k==='payments.qr_image'&&qrFile&&qrFile.size)continue;if(k.startsWith('store.'))store[k.slice(6)]=v;else if(k.startsWith('payments.'))payments[k.slice(9)]=v;else if(k.startsWith('policies.'))policies[k.slice(9)]=v;}for(const key of ['upi_enabled','whatsapp_enabled','telegram_enabled'])payments[key]=f.has('payments.'+key);policies.account_sales_enabled=f.has('policies.account_sales_enabled');try{await put('/api/admin/settings',{store,payments,policies});toast('Settings saved');loadConfig().then(render)}catch(err){toast(err.message,true)}};
    }
    if(adminTab==='settings'){
      $('#inventory-export').onclick=async()=>{try{const data=await api('/api/admin/export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='daddys-store-inventory-backup.json';a.click();URL.revokeObjectURL(url);$('#inventory-backup-status').textContent='Inventory backup downloaded.'}catch(err){toast(err.message,true)}};
      $('#inventory-import').onclick=async()=>{const file=$('#inventory-import-file').files[0];if(!file){toast('Choose a JSON backup file first',true);return}try{const data=JSON.parse(await file.text());const result=await post('/api/admin/import',data);$('#inventory-backup-status').textContent=`Imported: ${result.merged.catalog} catalog items, ${result.merged.uc_packages} UC packages, ${result.merged.accounts} new accounts. Existing SKUs were updated.`;toast('Inventory backup imported');await renderAdmin()}catch(err){toast(err.message,true)}};
      $('#admin-password-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await post('/api/admin/change-password',{current_password:f.get('current_password'),new_password:f.get('new_password')});toast('Password changed. Sign out and sign in again.');}catch(err){toast(err.message,true)}};
    }
    if(adminTab==='audit'){const r=await api('/api/admin/audit');$('#audit-list').innerHTML=r.items.length?`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Entity</th><th>Reference</th><th>Detail</th></tr></thead><tbody>${r.items.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td>${esc(x.action)}</td><td>${esc(x.entity)}</td><td>${esc(x.entity_id)}</td><td>${esc(x.detail)}</td></tr>`).join('')}</tbody></table></div>`:empty('No activity yet','Admin changes will appear here.')}
  }
  async function uploadFile(file){const fd=new FormData();fd.append('file',file);return await api('/api/admin/upload',{method:'POST',body:fd});}
  function bindAccountForm(){const form=$('#account-form');$('#close-account-editor').onclick=()=>$('#account-editor').innerHTML='';form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);let gallery=lines(f.get('gallery'));for(const file of f.getAll('gallery_files')){if(file&&file.size){try{const u=await uploadFile(file);gallery.push(u.url)}catch(err){toast('Gallery upload failed: '+err.message,true);return}}}let videoUrl=f.get('video_url')||'';const videoFile=f.get('video_file');if(videoFile&&videoFile.size){try{const u=await uploadFile(videoFile);videoUrl=u.url}catch(err){toast('Video upload failed: '+err.message,true);return}}let glacier={};try{glacier=json(f.get('glacier_images'),{});if(typeof glacier!=='object'||Array.isArray(glacier))throw new Error()}catch{toast('Glacier images must be valid JSON',true);return}for(let n=1;n<=7;n++){const file=f.get('glacier_file_'+n);if(file&&file.size){try{glacier[String(n)]=(await uploadFile(file)).url}catch(err){toast('Glacier level '+n+' upload failed: '+err.message,true);return}}}const inventory={};for(const k of ['suits','xsuits','guns','vehicles','helmets','backpacks','parachutes','emotes','companions','collectibles'])inventory[k]=lines(f.get(k));const data={title:f.get('title'),sku:f.get('sku'),description:f.get('description'),price:+f.get('price'),status:f.get('status'),featured:f.has('featured'),verified:f.has('verified'),account_level:+f.get('account_level'),mythic_count:+f.get('mythic_count'),legendary_count:+f.get('legendary_count'),xsuit_count:+f.get('xsuit_count'),gun_labs:+f.get('gun_labs'),glacier_level:+f.get('glacier_level'),rp_level:+f.get('rp_level'),inventory,gallery,glacier_images:glacier,video_url:videoUrl,catalog_item_ids:f.getAll('catalog_item_ids')};try{if(accountEditing)await put(`/api/admin/accounts/${accountEditing}`,data);else await post('/api/admin/accounts',data);toast('Account listing saved');renderAdmin()}catch(err){toast(err.message,true)}}}
  function bindCatalogForm(){const form=$('#catalog-form');$('#close-catalog-editor').onclick=()=>$('#catalog-editor').innerHTML='';form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);let imageUrl=f.get('image_url');const imageFile=f.get('item_image');if(imageFile&&imageFile.size){try{const u=await uploadFile(imageFile);imageUrl=u.url}catch(err){toast('Image upload failed: '+err.message,true);return}}const data={name:f.get('name'),category:f.get('category'),rarity:f.get('rarity'),image_url:imageUrl,description:f.get('description'),metadata:{},active:f.has('active')};try{if(catalogEditing)await put(`/api/admin/catalog/${catalogEditing}`,data);else await post('/api/admin/catalog',data);toast('Catalog item saved');renderAdmin()}catch(err){toast(err.message,true)}}}
  function bindUCForm(){const form=$('#uc-form');$('#close-uc-editor').onclick=()=>$('#uc-editor').innerHTML='';form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);const data={name:f.get('name'),sku:f.get('sku'),uc_amount:+f.get('uc_amount'),price:+f.get('price'),description:f.get('description'),active:f.has('active'),sort_order:+f.get('sort_order')};try{if(ucEditing)await put(`/api/admin/uc/${ucEditing}`,data);else await post('/api/admin/uc',data);toast('UC package saved');renderAdmin()}catch(err){toast(err.message,true)}}}

  async function bindGlobal(){
    view.addEventListener('click',async e=>{
      const a=e.target.closest('[data-account]');if(a){activeDetailTab='overview';activeGlacierLevel=7;navigate('account/'+a.dataset.account);return}
      const w=e.target.closest('[data-wishlist]');if(w){toggleWishlist(w.dataset.wishlist);return}
      const c=e.target.closest('[data-compare]');if(c){toggleCompare(c.dataset.compare);return}
      const u=e.target.closest('[data-add-uc]');if(u){const arr=cart();const old=arr.find(x=>x.type==='uc'&&x.id===u.dataset.addUc);if(old)old.quantity++;else arr.push({type:'uc',id:u.dataset.addUc,quantity:1});set(LS.cart,arr);updateCartCount();toast('UC package added to cart');return}
      const l=e.target.closest('[data-glacier-level]');if(l)return;
    });
  }
  $('#menu-toggle').onclick=()=>$('#main-nav').classList.toggle('open');
  $('#main-nav').addEventListener('click',()=>$('#main-nav').classList.remove('open'));
  window.addEventListener('hashchange',()=>{render().catch(e=>toast(e.message,true))});
  $('#year').textContent=new Date().getFullYear();
  (async()=>{await loadConfig();await bindGlobal();await render();updateCartCount()})();
})();